import os
import threading
import time

from core.evidence_lifecycle import (
    EVIDENCE_DIR,
    cleanup_evidence,
    discover_evidence,
    evidence_status
)


# ============================================================
# SENTINEL PHOENIX
# EVIDENCE BRIDGE V1
#
# Connects existing UNKNOWN evidence generated by
# face_identity.py to Evidence Lifecycle.
#
# Existing flow:
#
# UNKNOWN PERSON
#      ↓
# face_identity.py saves local evidence image
#      ↓
# evidence_bridge.py discovers it automatically
#      ↓
# evidence_lifecycle.py registers it
#      ↓
# TTL / count / storage policy
#
# This module does NOT modify face_identity.py.
# ============================================================


EVIDENCE_BRIDGE_VERSION = "1.0"


# ============================================================
# CONFIGURATION
# ============================================================

# Look for newly-created UNKNOWN evidence every 10 seconds.

SCAN_INTERVAL_SECONDS = 10


# Full lifecycle cleanup every 60 seconds.

CLEANUP_INTERVAL_SECONDS = 60


_STOP_EVENT = threading.Event()


# ============================================================
# RUN ONE DISCOVERY
# ============================================================

def discover_new_evidence():

    try:

        results = discover_evidence()

    except Exception as error:

        return {
            "status": "ERROR",
            "stage": "DISCOVERY",
            "reason": str(error)
        }

    registered = []

    already_registered = []

    errors = []

    for result in results:

        status = result.get(
            "status"
        )

        if status == "REGISTERED":

            registered.append(
                result.get(
                    "evidence_id"
                )
            )

        elif status == "ALREADY_REGISTERED":

            already_registered.append(
                result.get(
                    "evidence_id"
                )
            )

        elif status not in (
            None,
            "NOT_FOUND"
        ):

            errors.append(
                result
            )

    return {
        "status": "DISCOVERY_COMPLETE",
        "registered": registered,
        "already_registered":
            already_registered,
        "errors": errors
    }


# ============================================================
# ONE COMPLETE MAINTENANCE CYCLE
# ============================================================

def run_once(
    cleanup=True
):

    discovery = discover_new_evidence()

    if cleanup:

        try:

            cleanup_result = cleanup_evidence()

        except Exception as error:

            cleanup_result = {
                "status": "ERROR",
                "reason": str(error)
            }

    else:

        cleanup_result = {
            "status": "SKIPPED"
        }

    try:

        status = evidence_status()

    except Exception as error:

        status = {
            "status": "ERROR",
            "reason": str(error)
        }

    return {
        "status": "BRIDGE_CYCLE_COMPLETE",
        "version": EVIDENCE_BRIDGE_VERSION,
        "discovery": discovery,
        "cleanup": cleanup_result,
        "evidence": status
    }


# ============================================================
# BACKGROUND WORKER
# ============================================================

def _background_worker():

    print(
        "[EVIDENCE] Lifecycle bridge online."
    )

    print(
        "[EVIDENCE] Watching:"
    )

    print(
        "[EVIDENCE]",
        EVIDENCE_DIR
    )

    last_cleanup = 0.0

    while not _STOP_EVENT.is_set():

        now = time.monotonic()

        do_cleanup = (
            now
            -
            last_cleanup
            >=
            CLEANUP_INTERVAL_SECONDS
        )

        result = run_once(
            cleanup=do_cleanup
        )

        discovery = result.get(
            "discovery",
            {}
        )

        registered = discovery.get(
            "registered",
            []
        )

        if registered:

            print(
                "[EVIDENCE] New UNKNOWN evidence:",
                len(
                    registered
                )
            )

            for evidence_id in registered:

                print(
                    "[EVIDENCE] Registered:",
                    evidence_id
                )

        if do_cleanup:

            cleanup_result = result.get(
                "cleanup",
                {}
            )

            deleted = cleanup_result.get(
                "deleted",
                []
            )

            if deleted:

                print(
                    "[EVIDENCE] Automatic cleanup:",
                    len(
                        deleted
                    ),
                    "item(s) deleted."
                )

            last_cleanup = now

        _STOP_EVENT.wait(
            SCAN_INTERVAL_SECONDS
        )

    print(
        "[EVIDENCE] Lifecycle bridge stopped."
    )


# ============================================================
# START BACKGROUND WATCHER
# ============================================================

def start_background():

    if not _STOP_EVENT.is_set():

        # Make sure a previous run
        # does not remain stopped.

        _STOP_EVENT.clear()

    thread = threading.Thread(
        target=_background_worker,
        name="sentinel-evidence-lifecycle",
        daemon=True
    )

    thread.start()

    return thread


# ============================================================
# STOP BACKGROUND WATCHER
# ============================================================

def stop_background():

    _STOP_EVENT.set()

    return {
        "status": "STOP_REQUESTED"
    }


# ============================================================
# RUN FOREVER
# ============================================================

def run_forever():

    _STOP_EVENT.clear()

    # Immediate scan when Sentinel starts.

    initial = run_once(
        cleanup=True
    )

    print(
        "[EVIDENCE] Initial lifecycle scan:"
    )

    print(
        initial
    )

    try:

        _background_worker()

    except KeyboardInterrupt:

        print("")

        print(
            "[EVIDENCE] Shutdown requested."
        )

    finally:

        _STOP_EVENT.set()


# ============================================================
# SELF TEST
# ============================================================

def self_test():

    directory_exists = os.path.isdir(
        EVIDENCE_DIR
    )

    try:

        discovery = discover_new_evidence()

        discovery_ok = (
            discovery.get(
                "status"
            )
            ==
            "DISCOVERY_COMPLETE"
        )

    except Exception:

        discovery_ok = False

    try:

        lifecycle_status = evidence_status()

        lifecycle_online = (
            lifecycle_status.get(
                "status"
            )
            ==
            "ONLINE"
        )

    except Exception:

        lifecycle_online = False

    passed = all(
        [
            directory_exists,
            discovery_ok,
            lifecycle_online
        ]
    )

    return {
        "status":
            (
                "PASS"
                if passed
                else
                "FAIL"
            ),

        "version":
            EVIDENCE_BRIDGE_VERSION,

        "evidence_directory":
            EVIDENCE_DIR,

        "directory_exists":
            directory_exists,

        "discovery":
            discovery_ok,

        "lifecycle":
            lifecycle_online,

        "scan_interval_seconds":
            SCAN_INTERVAL_SECONDS,

        "cleanup_interval_seconds":
            CLEANUP_INTERVAL_SECONDS,

        "flow": [
            "UNKNOWN_DETECTED",
            "LOCAL_PHOTO_CREATED",
            "AUTO_DISCOVERY",
            "LIFECYCLE_REGISTER",
            "TTL_POLICY",
            "COUNT_POLICY",
            "STORAGE_POLICY"
        ],

        "safety": {
            "local_only":
                True,

            "modifies_face_identity":
                False,

            "internet_upload":
                False,

            "shell_execution":
                False,

            "payload_execution":
                False,

            "arbitrary_file_delete":
                False
        }
    }


# ============================================================
# ENTRY POINT
# ============================================================

if __name__ == "__main__":

    run_forever()